		}

		ctx, cancel := context.WithTimeout(
			r.Context(), time.Second*time.Duration(timeout))
		defer cancel()

		// Check if the context has a reasonable timeout
		deadline, ok := ctx.Deadline()
		if !ok {
			fmt.Fprintf(w, "No deadline set\n")
